clues = {4: 6, 5: 9, 6: 8, **{k: 5 for k in range(-15, -8)}}
valid = []
for p in range(1, 31):
    residues = {}
    ok = True
    for off, color in clues.items():
        r = off % p
        if r in residues and residues[r] != color:
            ok = False
            break
        residues[r] = color
    if ok:
        valid.append((p, [residues.get(i, 0) for i in range(p)]))
print('valid candidate periods:', [p for p, _ in valid])
print('smallest candidate sequence (unobserved residue default 0):', valid[0])
p = valid[0][0]
seq = valid[0][1]
grid = [[seq[(j-i) % p] for j in range(16)] for i in range(16)]
print('16x16 conditional grid, p=11:')
for row in grid:
    print(' '.join(map(str, row)))
